contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address key, bool status) public {
        // Exclude the zero address, which the buggy check treats as "owner";
        // any non-zero caller is a valid admissible non-owner.
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // Baseline value before any authorization.
        bool before = c.approvedLoggers(key);

        // A non-owner attempts to authorize a logger.
        vm.prank(caller);
        c.setApprovedLogger(key, status);

        // General rule: a non-owner caller can never change the mapping.
        assertTrue(c.approvedLoggers(key) == before);
    }
