pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address victim, bool status) public {
        // Admissible domain: keep it WIDE — any caller (including owner address(0)),
        // any victim key (possibly different from the caller), any status flag.
        vm.assume(uint256(uint160(victim)) != 0);

        // Snapshot the victim's authorization state before the call.
        bool before = c.approvedLoggers(victim);
        if (!before) before = c.approvedToLog(victim);

        // Drive c through setApprovedLogger from the fuzzed caller.
        vm.prank(caller);
        bool ok;
        try c.setApprovedLogger(victim, status) {
            ok = true;
        } catch {
            ok = false;
        }

        bool after_ = c.approvedLoggers(victim);
        if (!after_) after_ = c.approvedToLog(victim);

        // General rule: either the caller is the contract owner (address(0)) and the
        // write succeeds, or the call reverts and the victim's entry is unchanged.
        // The mutant lets ANY non-zero caller succeed and write `status`, so for
        // e.g. caller != address(0) and status == true it writes true where the
        // reference reverts and leaves the entry untouched — breaking the rule.
        assertTrue(
            (caller == address(0))
                ? (ok && after_ == status)
                : (!ok && after_ == before)
        );
    }
}

