contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address key, bool status) public {
        // The buggy owner-check only admits address(0); any real address is a non-owner.
        vm.assume(caller != address(0));
        vm.assume(key != address(0));

        bool ok;
        vm.prank(caller);
        try c.setApprovedLogger(key, status) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a non-owner call can never grant logging rights.
        // In P the call reverts (ok == false); in M it succeeds and sets approvedLoggers(key).
        assertTrue(!(ok && c.approvedLoggers(key)));
    }
}

