contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address logger) public {
        // the owner is the deployer (this test contract); logger must be an
        // ordinary external address distinct from the owner
        vm.assume(logger != address(this));

        // owner approves, then revokes: net effect must be "not approved"
        vm.startPrank(address(this));
        c.setApprovedLogger(logger, true);
        c.setApprovedLogger(logger, false);
        vm.stopPrank();

        assertTrue(
            c.approvedToLog(logger) == false,
            "approval then revocation must leave the logger unapproved"
        );
    }
}

