pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this); // deployer becomes _contractOwner
    }

    function testFuzz_property(address logger, bool status) public {
        // Admissible domain: any logger other than the owner itself
        // (when logger == msg.sender the mutant is indistinguishable).
        vm.assume(logger != owner);

        vm.prank(owner);
        c.setApprovedLogger(logger, status);

        // General rule: approving an address sets THAT address's flag to the
        // requested status, and does not disturb the owner's own flag.
        assertTrue(c.approvedToLog(logger) == status && !c.approvedToLog(owner));
    }
}

