pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address logger) public {
        address owner = address(this); // deployer of c is the contract owner
        vm.assume(logger != owner);
        vm.assume(!c.approvedToLog(owner));
        vm.assume(!c.approvedToLog(logger));

        vm.prank(owner);
        c.setApprovedLogger(logger, true);

        // General rule: granting approval to logger makes logger approved
        // and leaves the owner's own approval flag untouched.
        assertTrue(
            c.approvedToLog(logger) && !c.approvedToLog(owner),
            "owner flag must stay false when granting logger"
        );
    }
}

