contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address logger, address keep) public {
        c.setApprovedLogger(logger, true);
        // caller must be the approved logger to satisfy the guard in P
        (bool ok, ) = address(this).call(abi.encodeWithSignature("callLog(address,address)", logger, keep));
        require(ok, "subcall failed");
        assert(gotReturn);
    }

    bool gotReturn;

    function callLog(address logger, address keep) public {
        // simulate msg.sender == logger is impossible; instead do the call logic inline
        // We rely on the test entry point being called by an approved logger.
        bool r = c.logCreated(keep);
        gotReturn = r;
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address _caller, address _keepAddress) public {
        require(!c.approvedToLog(_caller), "precondition");
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.logCreated.selector, _keepAddress)
        );
        require(ok, "call failed");
        bool returned = abi.decode(ret, (bool));
        assert(!returned);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address logger, address unapproved, address keep) public {
        require(unapproved != logger, "same");
        c.setApprovedLogger(logger, true);
        bool ok1 = c.logCreated(keep);
        assert(ok1);
        // unapproved caller: deployer/test contract is not an approved logger
        bool ok2 = c.logCreated(keep);
        assert(!ok2);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(true);
        bool obs = c.logCreated(address(0x1234));
        bool approved = c.approvedToLog(address(this));
        assert(obs == approved);
    }
    receive() external payable {}
}

